/* Mobile home exposes the same five primary destinations as the desktop shell. */
(()=>{
const mobile=matchMedia('(max-width:700px)'),root=document.documentElement;
const hub=document.createElement('section');hub.id='mobile-dashboard';hub.setAttribute('aria-label','Main dashboard');hub.innerHTML='<div class="mobile-welcome"><span class="mobile-eyebrow">FN CLINICAL · WORKSPACE</span><h1>Your care workspace</h1><p>Patients, actions and review. One place to start.</p></div><div id="mobile-sections"></div><div class="shell-mobile-more"><button onclick="go(\'Resources\')">Resources & administration →</button></div><div class="mobile-shortcuts"></div><p class="mobile-footnote">Synthetic training environment</p>';
document.querySelector('#app').before(hub);
const home=document.createElement('button');home.className='btn mobile-home-button';home.textContent='Dashboard';home.setAttribute('aria-label','Back to main dashboard');document.querySelector('.top').prepend(home);
function show(){root.classList.add('mobile-home');draw();window.scrollTo({top:0,behavior:'instant'})}home.onclick=show;window.fnMobile={home:show};
const originalGo=window.go;window.go=function(...args){const result=originalGo.apply(this,args);if(mobile.matches)root.classList.remove('mobile-home');return result};
const brand=document.querySelector('.brand');brand.addEventListener('click',e=>{if(mobile.matches){e.preventDefault();e.stopImmediatePropagation();show()}},true);
const info={'Team workspace':'Tasks, handovers and open escalations','Patients':'All patients and training cohorts','New assessment':'Enter findings and review a suggested pathway','Follow-up':'Changes, actions and decisions','Results':'Reports and results needing review'};
function draw(){const target=hub.querySelector('#mobile-sections');target.replaceChildren();const grid=document.createElement('div');grid.className='mobile-tile-grid';target.append(grid);for(const node of document.querySelectorAll('#nav button[data-primary]')){const card=document.createElement('button');card.className='mobile-tile';const svg=node.querySelector('svg');if(svg)card.append(svg.cloneNode(true));const title=node.querySelector('span').textContent;const strong=document.createElement('strong');strong.textContent=title;const small=document.createElement('small');small.textContent=info[title];card.append(strong,small);card.onclick=()=>{node.click();root.classList.remove('mobile-home');window.scrollTo({top:0,behavior:'instant'})};grid.append(card)}const shortcuts=hub.querySelector('.mobile-shortcuts');shortcuts.replaceChildren();for(const [label,detail,fn]of [['My account','Profile and settings',()=>window.fnAccount.load()],['Messages & calls','Team communications',()=>window.fnMessages.open()]]){const b=document.createElement('button');b.className='mobile-shortcut';const strong=document.createElement('strong');strong.textContent=label;const small=document.createElement('small');small.textContent=detail;b.append(strong,small);b.onclick=fn;shortcuts.append(b)}}
new MutationObserver(()=>{if(mobile.matches)draw()}).observe(document.querySelector('#nav'),{childList:true});mobile.addEventListener('change',()=>{if(mobile.matches)show()});if(mobile.matches)show();
})();
